import java.util.ArrayList;import java.util.Arrays;import java.util.List;class Solution {    public List<List<Integer>> permuteUnique(int[] nums) {        List<List<Integer>> result = new ArrayList<>();        List<Integer> currentPermutation = new ArrayList<>();        boolean[] used = new boolean[nums.length];        Arrays.sort(nums);        backtrack(result, currentPermutation, used, nums);        return result;    }    private void backtrack(List<List<Integer>> result, List<Integer> currentPermutation, boolean[] used, int[] nums) {        if (currentPermutation.size() == nums.length) {            result.add(new ArrayList<>(currentPermutation));            return;        }        for (int i = 0; i < nums.length; i++) {            if (used[i]) {                continue;            }            if (i > 0 && nums[i] == nums[i-1] && !used[i-1]) {                continue;            }            currentPermutation.add(nums[i]);            used[i] = true;            backtrack(result, currentPermutation, used, nums);            used[i] = false;            currentPermutation.remove(currentPermutation.size() - 1);        }    }}